const form = create({ type: 'form', renderTo: host, items: [
  { type: 'textfield', name: 'slug', label: 'Slug' },
  { type: 'fieldlist', name: 'criteria', label: 'Criteria', items: [{ type: 'textfield', name: 'name' }], value: [{ name: 'Poise' }, { name: 'Walk' }] },
] });

try { await api.save(form.getValues()); }
catch (e) {
  const left = form.setErrors({ slug: 'Already in use', 'criteria.1.name': 'Repeated' }); // e.fieldErrors
  if (left.length) toast({ type: 'error', text: 'Not shown on a field: ' + left.join(', ') });
}

