const grid = create({
  type: 'grid', renderTo: host, store, resizableColumns: true, reorderableColumns: true,
  columns: [{ field: 'name', sortable: true }, { field: 'price', format: 'money' }],
  plugins: [persistState('grid-lots')],            // widths, order, sort, filters, page: per user, in the browser or your API
});
await exportGrid(grid, { format: 'xlsx', filename: 'lots' }); // visible columns, current sort and filters, every page ('csv' too)
await printGrid(grid, { title: 'Lots' });                      // a plain table: header on every page, none of the app around it
setStateStorage({ get: (k) => api.getPref(k), set: (k, v) => api.setPref(k, v) }); // optional: follow the user

