chart.code:
const votes = new Store({ data: [{ id: 1, name: 'Amara', votes: 120 }, { id: 2, name: 'Bianca', votes: 95 }] });
create({ type: 'container', layout: 'hbox', gap: 16, renderTo: host, items: [
  { type: 'grid', flex: 1, store: votes, columns: [{ field: 'name' }, { field: 'votes' }] },
  { type: 'chart', flex: 1, kind: 'bar', x: 'name', series: ['votes'], store: votes, title: 'Votes' },
] });

// from a server (SSE or a WebSocket), a message is { op?: 'upsert' | 'remove', data?, id? } or an array of them
const stop = votes.connect(new EventSource('/events/votes'));
// or by hand: a known id is patched in place (not an edit), an unknown one is added
votes.applyPatches([{ data: { id: 1, votes: 121 } }, { op: 'remove', id: 2 }]);

