rowediting.code:
const grid = create({ type: 'grid', renderTo: host, store, columns, plugins: [rowEditing()] });
grid.on('before-edit', (rec) => rec.get('locked') !== true);            // return false to refuse
grid.on('edit', async (rec, values, old) => {                           // only the changed fields
  try { await api.patch(rec.id, values); rec.commit(); }
  catch (e) { for (const k in old) rec.set(k, old[k]); toast({ type: 'error', text: 'Not saved' }); }
});

